int p_levels;
int p_major;
int p_drift;
int p_sweeps;
float p_trail;
bool p_rings;
bool p_showReticle;
float p_reticleX;
float p_reticleY;
int p_beats;
float p_hitAmt;
float p_hit;
float p_exposure;
float p_vignette;
bool p_hud;
float p_readout;
float2 v_reticle() { return float2(p_reticleX, p_reticleY); }
MTex u_source;
float u_sourceOn;
float2 u_sourceSize;
float u_sourceTime;
float4 m_source(float2 q) { return M_tex(u_source, M_clamp(q, float2(0.0), float2(1.0))); }
float4 m_sourcePx(float2 fc) { return m_source(fc / u_res); }
