float4 motif(float2 uv, float2 fc) {
  float2 q=fc/u_res,A=M_asp();
  float k=M_min(W_drive(),1.2);
  float l=pow(W_lb(q),0.5);
  float3 img=W_src(q);
  float3 col=float3(luma(img))*u_a1*0.28+img*0.06;
  
  float lim=u_safe>0.5?3.0*u_L:1.0e4;
  float dft=sign(float(p_drift))*floor(M_min(float(abs(p_drift)*p_major),lim)/float(p_major))*float(p_major);
  float x=l*float(p_levels)-dft*u_p;
  float fw=fwidth(x)+1e-4,fr=fract(x),dd=M_min(fr,1.0-fr);
  float maj=M_step(M_mod(floor(x+0.5),float(p_major)),0.5);
  float ln=1.0-M_smoothstep(0.0,fw*(1.4+maj*1.4),dd);
  float3 lc2=M_mix(u_a1,u_a0,M_smoothstep(0.1,0.7,l));
  float ang=atan2(uv.y,uv.x);
  float sw=fract(-ang/TAU-safeCycles(float(p_sweeps))*u_p);
  float trail=exp(-sw*p_trail);
