float4 W_fore(float2 qq) {
  if(u_foreOn>0.5){
    float4 f=m_fore(M_clamp(qq,float2(0.0),float2(1.0)));
    if(p_lumaKey&&f.a>0.999){
      float a=M_smoothstep(p_keyLevel,p_keyLevel*3.0+0.001,luma(f.rgb));
