inline float3 M_max(float3 a, float b) { return metal::max(a, float3(b)); }
inline float3 M_clamp(float3 x, float lo, float hi) { return metal::clamp(x, float3(lo), float3(hi)); }
inline float3 M_mix(float3 a, float3 b, float t) { return metal::mix(a, b, float3(t)); }
