float luma(float3 c) { return dot(c, float3(0.2126, 0.7152, 0.0722)); }
float2 lc(float k, float ph) { float a = TAU * (k * u_p + ph); return float2(cos(a), sin(a)); }
float lsin(float k, float ph) { return sin(TAU * (k * u_p + ph)); }
float lsaw(float k, float ph) { return fract(k * u_p + ph); }
float4 M_mod289(float4 x) { return x - floor(x * (1.0 / 289.0)) * 289.0; }
float3 M_mod289(float3 x) { return x - floor(x * (1.0 / 289.0)) * 289.0; }
float M_mod289(float x) { return x - floor(x * (1.0 / 289.0)) * 289.0; }
