  float2 dir=normalize(uv+float2(1e-4))/A;
  float3 col=float3(W_src(q+dir*amt).r,W_src(q).g,W_src(q-dir*amt).b);
  if(p_spectral){
    float3 acc=float3(0.0);
    for(int i=0;i<7;i++){
      float t=float(i)/6.0;
      float3 w=0.5+0.5*cos(TAU*(t+float3(0.0,0.33,0.67)));
      acc+=W_src(q+dir*amt*(t*2.0-1.0)*1.4)*w;
