float2 M_asp() { return u_res / M_min(u_res.x, u_res.y); }
float4 buf(MTex b, float2 fc) { return M_tex(b, fc / u_res); }
float p_originX;
float p_originY;
float p_speed;
float p_refract;
float p_sharp;
int p_rings;
float p_chroma;
float p_glow;
int p_beats;
float p_hitAmt;
float p_hit;
float p_exposure;
float p_vignette;
bool p_hud;
float p_readout;
float2 v_origin() { return float2(p_originX, p_originY); }
MTex u_source;
float u_sourceOn;
float2 u_sourceSize;
float u_sourceTime;
