  float2 disp=float2(0.0);
  float glow=0.0;
  if(r>=1.0){
    for(int i=0;i<3;i++){
      if(i>=p_rings) break;
      float age=fract(u_p*r)+float(i);
      float R=age*p_speed;
      float amp=exp(-age*1.1)*(i==0?1.0:0.75)*(p_hitAmt+p_hit*1.5);
