  float slot=tslot(float(p_rate));
  float rows=float(p_bands),b=floor(q.y*rows);
  float h=h21(float2(b,slot));
  float on=M_step(1.0-(0.10+0.45*p_tear)*(0.35+0.65*M_min(k,1.0)),h);
  float sh=(h21(float2(b,slot+7.0))-0.5)*0.32*p_tear*on*(0.3+k);
  float cb=floor(q.x*8.0);
  float hv=h21(float2(cb+31.0,slot));
  float ov=M_step(0.94-0.12*M_min(k,1.0),hv)*p_blocks;
  float2 u2=q+float2(sh,0.0)+float2(0.0,ov*(h21(float2(cb,slot+3.0))-0.5)*0.2);
